const testPath='tech-checks/operations/tests/owner-equipment.test.mjs';let tests=fs.readFileSync(testPath,'utf8');if(!tests.includes('placement-only Owner edit retains existing definitive connection'))tests+=`\ntest('placement-only Owner edit retains existing definitive connection',()=>{const c=control({productId:'1001',settings:{...settings,publicIp:'',ports:[],monitoringEnabled:false}}),m=projectOwnerMap(f.field,[c]),r=projectOwnerConnections(f.connections,[c]);assert.equal(r.items.find(p=>p.productId==='1001').status,'online');assert.equal(mhelpFieldHealth(m.uploadInventory,m.fleetRoster,f.rows,f.now,r).items.find(p=>p.productId==='1001').state,'online');});\n`;
if(!tests.includes('placement-only override cannot release another tracker IP claim'))tests+=`\ntest('placement-only override cannot release another tracker IP claim',()=>{const other=control({productId:'1008',settings:{...settings,publicIp:'',ports:[],monitoringEnabled:false}});assert.throws(()=>assertTarget('1006','8.8.8.8',[other],{rows:[{productId:'1008',ip:'8.8.8.8'}],observedAt:f.fresh}));});\ntest('Verify all delegates placement-only targets to the existing checker',async()=>{const calls=[],c=control({settings:{...settings,publicIp:'',ports:[],monitoringEnabled:false}});const handler=createOwnerHandler({now:()=>f.now,fetch:async(_url,options)=>{const p=JSON.parse(options.body);calls.push(p.path);return Response.json(p.path==='/api/session'?{authorized:true,legacyOwner:true,role:'Owner',productionOwnerUserId:'00000000-0000-4000-8000-000000000001'}:{contract:'COS_VERIFY_PRODUCTS_NOW_V1',items:[],connections:null});},rpc:async(name)=>{assert.equal(name,'cos_owner_equipment_list_v1');return [c];},tracker:async()=>{throw Error('Unexpected tracker read');},probe:async()=>{throw Error('Unexpected Owner probe');}});const r=await handler(new Request('https://example.invalid',{method:'POST',headers:{authorization:'Bearer synthetic-only','content-type':'application/json'},body:JSON.stringify({path:'/api/product-connections/verify',method:'POST',body:{productIds:['1006']}})}));assert.equal(r.status,200);assert.deepEqual(calls,['/api/session','/api/product-connections/verify']);});\n`;
fs.writeFileSync(testPath,tests);
